/**
 * Row types for the tables created by the migrations in ./migrations.
 * Keep in sync with the migrations (the data-layer tests exercise both).
 *
 * Portable storage conventions (work identically on SQLite and PostgreSQL):
 * - ids: text UUIDs generated by the application
 * - timestamps: text ISO-8601 UTC ('2026-10-03T04:15:00.000Z')
 * - calendar dates: text 'YYYY-MM-DD'; times of day: text 'HH:MM'
 * - controlled values: text with CHECK constraints (no native enums)
 * - lifecycle: `status` text (ACTIVE/INACTIVE …) instead of booleans or hard deletes
 */
export interface Database {
  school_settings: SchoolSettingsTable;
  academic_years: AcademicYearsTable;
  classes: ClassesTable;
  sections: SectionsTable;
  subjects: SubjectsTable;
  periods: PeriodsTable;
  users: UsersTable;
  teachers: TeachersTable;
  teacher_subjects: TeacherSubjectsTable;
  class_teacher_assignments: ClassTeacherAssignmentsTable;
  students: StudentsTable;
  enrolments: EnrolmentsTable;
  audit_logs: AuditLogsTable;
}

interface Timestamps {
  created_at: string;
  updated_at: string;
}

export interface SchoolSettingsTable extends Timestamps {
  id: string;
  short_name: string;
  full_name: string;
  primary_color: string;
  logo_path: string | null;
  address: string | null;
  phone: string | null;
  email: string | null;
}

export interface AcademicYearsTable extends Timestamps {
  id: string;
  label: string;
  start_date: string;
  end_date: string;
  status: string;
}

export interface ClassesTable extends Timestamps {
  id: string;
  name: string;
  display_order: number;
  status: string;
}

export interface SectionsTable extends Timestamps {
  id: string;
  class_id: string;
  name: string;
  status: string;
}

export interface SubjectsTable extends Timestamps {
  id: string;
  name: string;
  code: string | null;
  status: string;
}

export interface PeriodsTable extends Timestamps {
  id: string;
  academic_year_id: string;
  sequence: number;
  period_number: number | null;
  kind: string;
  label: string;
  start_time: string;
  end_time: string;
  status: string;
}

export interface UsersTable extends Timestamps {
  id: string;
  username: string;
  role: string;
  status: string;
}

export interface TeachersTable extends Timestamps {
  id: string;
  user_id: string;
  staff_code: string;
  full_name: string;
  phone: string | null;
  email: string | null;
  status: string;
}

export interface TeacherSubjectsTable {
  teacher_id: string;
  subject_id: string;
  created_at: string;
}

export interface ClassTeacherAssignmentsTable extends Timestamps {
  id: string;
  academic_year_id: string;
  section_id: string;
  teacher_id: string;
  status: string;
  assigned_on: string;
  ended_on: string | null;
}

export interface StudentsTable extends Timestamps {
  id: string;
  user_id: string;
  admission_number: string;
  full_name: string;
  date_of_birth: string | null;
  photo_path: string | null;
  status: string;
}

export interface EnrolmentsTable extends Timestamps {
  id: string;
  student_id: string;
  academic_year_id: string;
  section_id: string;
  roll_number: string | null;
  status: string;
  started_on: string;
  ended_on: string | null;
}

export interface AuditLogsTable {
  id: string;
  occurred_at: string;
  actor_user_id: string | null;
  action: string;
  entity_type: string;
  entity_id: string | null;
  before_json: string | null;
  after_json: string | null;
  reason: string | null;
  request_id: string | null;
}
